//! The remote port's durable files: the host's identity (`identity.json`)
//! and the devices paired with it (`devices.json`). Both are small files
//! beside `views.json`, written through the store's atomic path. The
//! certificate's private key is not here: it is a Keychain item under
//! [`Identity::key_account`].

use std::time::SystemTime;

use serde::{Deserialize, Serialize};
use uuid::Uuid;

/// The file names inside the data directory.
pub const IDENTITY_FILE: &str = "identity.json";
pub const DEVICES_FILE: &str = "devices.json";

/// The version of `identity.json` this build writes.
pub const IDENTITY_SCHEMA_VERSION: u32 = 1;

/// The port the host listens on unless the identity says otherwise.
pub const DEFAULT_REMOTE_PORT: u16 = 43187;

/// Who this installation is to a remote client, and how it listens.
/// Made once on first start and kept for the life of the data
/// directory; a second data directory has its own.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Identity {
    pub schema_version: u32,
    /// Stable, random; never derived from the hostname or an address.
    pub server_id: Uuid,
    /// The display name a client shows for this host.
    pub server_name: String,
    /// The self-signed certificate, DER, base64. Public.
    pub certificate: String,
    /// SHA-256 over the certificate's `SubjectPublicKeyInfo`, hex: what
    /// a client pins, so a certificate reissued over the same key still
    /// verifies.
    pub spki_sha256: String,
    pub created: SystemTime,
    /// How the port binds.
    #[serde(default)]
    pub listen: Listen,
}

impl Identity {
    /// The Keychain account the certificate's private key is filed
    /// under: one per installation, so two data directories under one
    /// macOS account never overwrite each other's keys.
    #[must_use]
    pub fn key_account(&self) -> String {
        format!("remote-key:{}", self.server_id)
    }
}

/// Where the remote port binds. Loopback only until the owner allows
/// devices on the local network.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Listen {
    /// Bind every interface rather than loopback alone.
    pub lan: bool,
    pub port: u16,
}

impl Default for Listen {
    fn default() -> Self {
        Self {
            lan: false,
            port: DEFAULT_REMOTE_PORT,
        }
    }
}

/// What a paired device may do. Set in the host's dialog, never over
/// the port.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Scope {
    /// Every view and content read.
    Read,
    /// Reads, and the commands that put text into a session.
    Control,
}

impl Scope {
    #[must_use]
    pub fn word(self) -> &'static str {
        match self {
            Self::Read => "read",
            Self::Control => "control",
        }
    }
}

/// One device the owner paired. The bearer token itself is never
/// stored: its SHA-256 is what a request's token is checked against.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct PairedDevice {
    pub id: Uuid,
    /// What the device called itself when it paired.
    pub name: String,
    pub scope: Scope,
    /// SHA-256 of the bearer token, hex.
    pub token_sha256: String,
    pub created: SystemTime,
    /// When the device last made an authenticated request.
    #[serde(default)]
    pub last_seen: Option<SystemTime>,
}

/// The two files on disk. A missing file reads as absent or empty; a
/// malformed one is an error the app reports rather than overwrites.
pub trait RemoteStore: Send {
    fn load_identity(&self) -> Result<Option<Identity>, String>;
    fn save_identity(&self, identity: &Identity) -> Result<(), String>;
    fn load_devices(&self) -> Result<Vec<PairedDevice>, String>;
    fn save_devices(&self, devices: &[PairedDevice]) -> Result<(), String>;
}

/// What the host advertises over Bonjour while it listens on the local
/// network: `_switchboard._tcp` under an instance name, with TXT records
/// a client can match against a known server before it connects. Never
/// a token, never key material: the key hash is read from `/info` over
/// the pinned connection, not from a multicast record anyone can send.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Advertisement {
    /// The Bonjour instance name: the display name with a short id
    /// suffix, so two installations on one machine stay distinct.
    pub instance: String,
    pub server_id: Uuid,
    pub server_name: String,
    pub port: u16,
}

impl Advertisement {
    /// The service type, as the client browses for it.
    pub const SERVICE: &'static str = "_switchboard._tcp";
    /// The protocol major version in the `v` TXT record.
    pub const PROTOCOL: &'static str = "1";

    #[must_use]
    pub fn new(server_id: Uuid, server_name: &str, port: u16) -> Self {
    Ok(sha256_hex(&key.subject_public_key_info()))
}

/// The server side of TLS: the identity's certificate over the key.
pub fn tls_config(identity: &Identity, key_pem: &str) -> Result<Arc<ServerConfig>, String> {
    let cert = CertificateDer::from(certificate_der(identity)?);
    let key = rcgen::KeyPair::from_pem(key_pem).map_err(|e| format!("key: {e}"))?;
    let key = PrivateKeyDer::Pkcs8(PrivatePkcs8KeyDer::from(key.serialize_der()));
    let config = ServerConfig::builder_with_provider(provider())
        .with_safe_default_protocol_versions()
        .map_err(|e| e.to_string())?
        .with_no_client_auth()
        .with_single_cert(vec![cert], key)
        .map_err(|e| e.to_string())?;
    Ok(Arc::new(config))
}

/// The crypto provider every connection uses: `ring`, which the tree
/// already builds. Named explicitly so a second provider in the tree
/// can never make the default ambiguous.
fn provider() -> Arc<CryptoProvider> {
    Arc::new(rustls::crypto::ring::default_provider())
}

/// A client that trusts exactly one public key, by the hash of its
/// `SubjectPublicKeyInfo`, and nothing else: no names, no dates, no
/// chain. What a paired device does on every connection; here for the
/// tests and for a Rust client.
pub fn pinned_client(spki_sha256: &str) -> Result<Arc<ClientConfig>, String> {
    let provider = provider();
    let config = ClientConfig::builder_with_provider(Arc::clone(&provider))
        .with_safe_default_protocol_versions()
        .map_err(|e| e.to_string())?
        .dangerous()
        .with_custom_certificate_verifier(Arc::new(Pin {
            spki_sha256: spki_sha256.to_owned(),
            provider,
        }))
        .with_no_client_auth();
    Ok(Arc::new(config))
}

#[derive(Debug)]
struct Pin {
    spki_sha256: String,
    provider: Arc<CryptoProvider>,
}

impl ServerCertVerifier for Pin {
    fn verify_server_cert(
        &self,
        end_entity: &CertificateDer<'_>,
        _intermediates: &[CertificateDer<'_>],
        _server_name: &ServerName<'_>,
        _ocsp_response: &[u8],
        _now: UnixTime,
    ) -> Result<ServerCertVerified, rustls::Error> {
        if spki_sha256_of_cert(end_entity).as_deref() == Some(self.spki_sha256.as_str()) {
            Ok(ServerCertVerified::assertion())
        } else {
            Err(rustls::Error::General(
                "the host's key is not the pinned one".into(),
            ))
        }
    }

    fn verify_tls12_signature(
        &self,
        message: &[u8],
        cert: &CertificateDer<'_>,
        dss: &DigitallySignedStruct,
    ) -> Result<HandshakeSignatureValid, rustls::Error> {
        rustls::crypto::verify_tls12_signature(
            message,
            cert,
            dss,
            &self.provider.signature_verification_algorithms,
        )
    }

    fn verify_tls13_signature(
        &self,
        message: &[u8],
        cert: &CertificateDer<'_>,
        dss: &DigitallySignedStruct,
    ) -> Result<HandshakeSignatureValid, rustls::Error> {
        rustls::crypto::verify_tls13_signature(
            message,
            cert,
            dss,
            &self.provider.signature_verification_algorithms,
        )
    }

    fn supported_verify_schemes(&self) -> Vec<SignatureScheme> {
        self.provider
            .signature_verification_algorithms
            .supported_schemes()
    }
}

/// SHA-256 of the certificate's `SubjectPublicKeyInfo`, hex. The
/// certificate is walked as DER: `Certificate { tbsCertificate {
/// [0] version, serialNumber, signature, issuer, validity, subject,
/// subjectPublicKeyInfo, .. }, .. }`, and the whole SPKI element is
/// hashed, which is what `rcgen::KeyPair::public_key_der` returns.
#[must_use]
pub fn spki_sha256_of_cert(der: &[u8]) -> Option<String> {
    let (0x30, tbs_and_rest, _) = der_element(der)? else {
        return None;
    };
    let (0x30, mut rest, _) = der_element(tbs_and_rest)? else {
        return None;
    };
    // The version is explicit and optional; rcgen writes it.
    if rest.first() == Some(&0xA0) {
        rest = der_element(rest)?.2;
    }
    for _ in 0..5 {
        rest = der_element(rest)?.2;
    }
    let (0x30, _, after) = der_element(rest)? else {
        return None;
    };
    Some(sha256_hex(&rest[..rest.len() - after.len()]))
}

/// One DER element: its tag, its content, and what follows it.
fn der_element(bytes: &[u8]) -> Option<(u8, &[u8], &[u8])> {
    let (&tag, after_tag) = bytes.split_first()?;
    let (&first, after_first) = after_tag.split_first()?;
    let (length, content_at) = if first < 0x80 {
        (usize::from(first), after_first)
    } else {
        let count = usize::from(first & 0x7f);
        if count == 0 || count > 4 || after_first.len() < count {
            return None;
        }
        let length = after_first[..count]
            .iter()
            .fold(0usize, |n, &b| (n << 8) | usize::from(b));
        (length, &after_first[count..])
    };
    if content_at.len() < length {
        return None;
    }
    let (content, rest) = content_at.split_at(length);
    Some((tag, content, rest))
}

/// Lowercase hex of SHA-256 over `bytes`.
#[must_use]
pub fn sha256_hex(bytes: &[u8]) -> String {
    Sha256::digest(bytes)
        .iter()
        .fold(String::with_capacity(64), |mut s, b| {
            let _ = write!(s, "{b:02x}");
            s
        })
}

/// The name a new identity starts with: the machine's short host name,
/// or "Switchboard" when it has none.
#[must_use]
pub fn default_server_name() -> String {
    std::process::Command::new("hostname")
        .arg("-s")
        .output()
        .ok()
        .and_then(|o| String::from_utf8(o.stdout).ok())
        .map(|s| s.trim().to_owned())
        .filter(|s| !s.is_empty())
        .unwrap_or_else(|| "Switchboard".into())
}

// --- random material

/// The pairing code's alphabet: Crockford's base 32, with no I, L, O
/// or U, so a code read aloud or typed is never ambiguous.
pub const CODE_ALPHABET: &[u8; 32] = b"0123456789ABCDEFGHJKMNPQRSTVWXYZ";
/// Eight characters of five bits: 40 bits, single use, three tries.
pub const CODE_LENGTH: usize = 8;

/// A fresh pairing code from the OS random source.
#[must_use]
pub fn pairing_code() -> String {
    let mut bytes = [0u8; CODE_LENGTH];
    fill_random(&mut bytes);
    bytes
        .iter()
        .map(|b| char::from(CODE_ALPHABET[usize::from(b % 32)]))
        .collect()
}

/// A fresh bearer token: 32 random bytes as base64url without padding,
/// 43 characters. It is shown to the device once and never stored.
#[must_use]
pub fn bearer_token() -> String {
    let mut bytes = [0u8; 32];
    fill_random(&mut bytes);
    base64::engine::general_purpose::URL_SAFE_NO_PAD.encode(bytes)
}

/// What `devices.json` keeps of a token.
#[must_use]
pub fn token_sha256(token: &str) -> String {
    sha256_hex(token.as_bytes())
}

fn fill_random(bytes: &mut [u8]) {
    // The OS random source failing is not something to carry on from.
    getrandom::fill(bytes).expect("the OS random source");
}

// --- HTTP

/// One request as it came off the socket, with what the frame needs
/// and nothing it does not: the bearer token is taken out of the
/// headers so it is never logged with them.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RemoteRequest {

