                let ad = Advertisement::new(identity.server_id, &identity.server_name, addr.port());
                if let Err(e) = self.services.advertiser.advertise(&ad) {
                    log::warn!("bonjour: {e}");
                }
            }
            _ => self.services.advertiser.withdraw(),
        }
    }

