    fn refuse(
        &self,
        request: &RemoteRequest,
        status: u16,
        code: &str,
        message: &str,
        authenticated: bool,
    ) -> RemoteReply {
        log::info!(
            "remote: {} {} refused: {code}",
            request.method,
            request.path
